import sympy
from sympy import abc
import math

# Top-level setup
# We work in a principal ideal domain (PID) such as the ring of integers Z or Q[x].
# Ideals in a PID are generated by a single element.
# A witness is expected to be a tuple (a, b, i, j) where:
#   a, b are elements of the ring R
#   i, j are the generators for the ideals I and J respectively.
# Alternatively, a dictionary with keys 'a', 'b', 'i', 'j' can be provided.

x = abc.x
y = abc.y
z = abc.z

def conditions(witness) -> list[bool]:
    try:
        # Unpack the witness
        if isinstance(witness, dict):
            a = witness.get('a')
            b = witness.get('b')
            i = witness.get('i', witness.get('I'))
            j = witness.get('j', witness.get('J'))
        elif isinstance(witness, (list, tuple)):
            if len(witness) == 4:
                a, b, i, j = witness
            elif len(witness) == 5:
                # Ignore the first element if the ring R is explicitly passed
                _, a, b, i, j = witness
            else:
                return [False, False]
        else:
            return [False, False]
            
        if a is None or b is None or i is None or j is None:
            return [False, False]
            
        # Extract single generators if ideals were passed as single-element lists/sets
        if isinstance(i, (list, tuple, set)) and len(i) == 1:
            i = list(i)[0]
        if isinstance(j, (list, tuple, set)) and len(j) == 1:
            j = list(j)[0]
            
        a = sympy.sympify(a)
        b = sympy.sympify(b)
        i = sympy.sympify(i)
        j = sympy.sympify(j)
            
        # H_1: R is a principal ideal domain
        # We assume the witness elements come from a standard PID (like Z or Q[x]).
        # If we can compute their LCM, we consider them valid elements of such a ring.
        h1 = True
        
        # Conclusion Q: I \cap J is generated by lcm(a, b)
        # In a PID, I = (i) and J = (j), so I \cap J = (lcm(i, j))
        gen_intersect = sympy.lcm(i, j)
        gen_ab = sympy.lcm(a, b)
        
        def generates_same_ideal(g1, g2):
            if g1 == g2:
                return True
            if g1 == 0 or g2 == 0:
                return False
            # Check if they divide each other (i.e., they are associates)
            try:
                q1, r1 = sympy.div(g1, g2)
                q2, r2 = sympy.div(g2, g1)
                if r1 == 0 and r2 == 0:
                    return True
            except Exception:
                pass
            # Fallback for integers or simple expressions
            try:
                return abs(g1) == abs(g2)
            except Exception:
                return False

        same_ideal = generates_same_ideal(gen_intersect, gen_ab)
        
        # The negated conclusion is True if they do NOT generate the same ideal
        neg_q = not same_ideal
        
        return [h1, neg_q]
    except Exception:
        return [False, False]

CONDITION_LABELS = [
    "H_1: R is a principal ideal domain",
    "¬Q: I \\cap J is not generated by lcm(a, b)"
]

